        <div className="id-card relative rounded-[30px] p-7 shadow-[0_35px_90px_rgba(19,78,58,.25)] sm:p-9"><div className="relative z-[1] flex items-center justify-between"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl border border-white/20 bg-white/10"><Fingerprint size={23}/></span><div><p className="text-[10px] uppercase tracking-[.18em] text-white/60">DigiCampus</p><p className="font-display text-sm font-bold">STUDENT IDENTITY</p></div></div><span className="rounded-full border border-white/20 px-3 py-1 text-[9px] font-bold uppercase tracking-[.15em]">Campus issued</span></div>
          <div className="relative z-[1] mt-14 flex items-end justify-between gap-5"><div><div className="mb-3 grid h-[76px] w-[76px] place-items-center rounded-2xl border border-white/25 bg-[#d9bd87] text-2xl font-bold text-[#174b3a]">ID</div><h2 className="font-display text-2xl font-extrabold tracking-tight sm:text-3xl">Student identity</h2><p className="mt-1 text-xs text-white/70">Your registered campus department</p><div className="mt-6 flex gap-8"><div><p className="text-[9px] uppercase tracking-[.16em] text-white/55">Student number</p><p className="mt-1 font-mono text-sm">•••• ••••</p></div><div><p className="text-[9px] uppercase tracking-[.16em] text-white/55">Credential</p><p className="mt-1 font-mono text-sm">CURRENT</p></div></div></div><div className="grid h-[104px] w-[104px] shrink-0 grid-cols-7 gap-[3px] rounded-xl bg-[#fbf8f0] p-3">{Array.from({length:49},(_,i)=><span key={i} className={((i*7+i*i+3)%5<2 ? 'bg-[#174b3a]' : 'bg-transparent') + ' rounded-[1px]'}/>)}</div></div></div>
