function useUserAuth() { const { isSignedIn, isLoaded } = useAuth(); return { isSignedIn: !!isSignedIn, isLoaded }; }
function PortalRedirect() {
  const { data: me, isLoading } = useGetMe();
  if (isLoading) return <CenteredLoading />;
  const route = me?.role === 'admin' ? '/admin' : me?.role === 'verifier' ? '/verifier' : me?.role === 'student' ? '/student' : '/register';
  return <Redirect to={route} />;
}
function CenteredLoading() { return <div className="grid min-h-[100dvh] place-items-center bg-background px-5"><div className="w-full max-w-md rounded-3xl border border-border bg-card p-7"><div className="flex items-center gap-3"><IconMark/><div><div className="h-4 w-40 animate-pulse rounded bg-muted"/><div className="mt-2 h-3 w-28 animate-pulse rounded bg-muted"/></div></div><div className="mt-8"><Skeleton rows={2}/></div></div></div>; }
function AuthPage({ kind }: { kind: 'in' | 'up' }) {
  return <main className="app-grain min-h-[100dvh] bg-[#f3f0e7]"><div className="mx-auto flex max-w-6xl items-center justify-between px-5 py-6 sm:px-10"><Brand/><Link href="/" className="inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground" data-testid="link-back-home"><ArrowLeft size={15}/> Back to campus</Link></div><div className="mx-auto grid max-w-6xl items-center gap-12 px-5 pb-12 pt-4 sm:px-10 lg:grid-cols-[1fr_480px]"><div className="hidden max-w-lg lg:block"><div className="mb-5 text-[11px] font-bold uppercase tracking-[.2em] text-[#b45f45]">DigiCampus ID · Secure access</div><h1 className="font-display text-5xl font-extrabold leading-[1.06] tracking-[-.05em]">Your campus.<br/><span className="text-primary">In your pocket.</span></h1><p className="mt-5 max-w-md leading-7 text-muted-foreground">A trusted digital identity for the places, services and people that make campus yours.</p><div className="mt-10 flex max-w-md gap-4 rounded-2xl border border-border bg-card p-5"><ShieldCheck className="mt-0.5 shrink-0 text-primary"/><p className="text-sm leading-6 text-muted-foreground">Your account is protected. Your digital ID is shared only when you choose to present it.</p></div></div><div className="flex min-h-[580px] items-center justify-center"><Show when="signed-out">{kind === 'in' ? <SignIn routing="path" path={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} /> : <SignUp routing="path" path={`${basePath}/sign-up`} signInUrl={`${basePath}/sign-in`} />}</Show><Show when="signed-in"><PortalRedirect/></Show></div></div></main>;
}

