function Gate({ role, children }: { role: 'student'|'verifier'|'admin'; children: ReactNode }) {
  const { isSignedIn, isLoaded } = useUserAuth(); const [, setLoc] = useLocation(); const { data: me, isLoading, isError, refetch } = useGetMe({ query: { enabled: isSignedIn && isLoaded, queryKey: getGetMeQueryKey() } });
  if (!isLoaded || (isSignedIn && isLoading)) return <CenteredLoading/>;
  if (!isSignedIn) return <Redirect to="/sign-in"/>;
  if (isError) return <div className="grid min-h-[100dvh] place-items-center p-5"><Notice title="Account status unavailable" detail="We could not confirm your campus role. Your access remains protected." retry={()=>refetch()}/></div>;
  if (me?.needsRegistration || me?.role === 'unregistered') return <Redirect to="/register"/>;
  if (me?.role !== role) {
    if (me?.role === 'admin') return <Redirect to="/admin"/>;
    if (me?.role === 'verifier') return <Redirect to="/verifier"/>;
    if (me?.role === 'student') return <Redirect to="/student"/>;
    setLoc('/register'); return null;
  }
  if (me.status !== 'active') return <AccessPending me={me}/>;
  return <>{children}</>;
}
function AccessPending({ me }: { me: CurrentAccount }) {
  const { signOut } = useClerk(); const rejected = me.status === 'rejected' || me.status === 'suspended';
  return <div className="app-grain grid min-h-[100dvh] place-items-center bg-[#f5f2ea] p-5"><div className="w-full max-w-[560px] rounded-[28px] border border-border bg-card p-7 shadow-[0_24px_70px_rgba(32,53,47,.08)] sm:p-10"><Brand/><div className={`mt-10 grid h-14 w-14 place-items-center rounded-2xl ${rejected?'bg-[#f7e8e3] text-[#a94237]':'bg-[#f5edcf] text-[#876b25]'}`}>{rejected?<CircleAlert size={25}/>:<Clock3 size={25}/>}</div><p className="mt-7 text-[10px] font-bold uppercase tracking-[.18em] text-muted-foreground">Campus access</p><h1 className="mt-2 font-display text-3xl font-extrabold tracking-tight">{rejected?'Access needs attention':'Your application is in review'}</h1><p className="mt-3 leading-7 text-muted-foreground">{rejected?'Your account is not currently active. Contact your campus administrator for next steps.':'A campus administrator is reviewing your registration. We will make your ID available as soon as approval is complete.'}</p><div className="mt-7 flex items-center justify-between rounded-xl border border-border bg-[#f7f4ec] px-4 py-3"><div><p className="text-xs text-muted-foreground">Application status</p><p className="mt-1 text-sm font-semibold">{me.role} access request</p></div><Status value={me.status}/></div><Button className="mt-7" variant="line" onClick={()=>signOut({redirectUrl:basePath||'/'})} testId="button-pending-signout"><LogOut size={15}/>Sign out</Button></div></div>;
}

function PageHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#b45f45]">{eyebrow}</p><h1 className="mt-2 font-display text-[clamp(1.8rem,4vw,2.5rem)] font-extrabold tracking-[-.045em]">{title}</h1>{description&&<p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div>;
}
function Panel({ children, className='' }: {children:ReactNode;className?:string}) { return <section className={`rounded-2xl border border-[#e0dbce] bg-[#fffdf8] shadow-[0_4px_18px_rgba(32,53,47,.025)] ${className}`}>{children}</section>; }
function Metric({label,value,sub,icon,accent=false}: {label:string;value:ReactNode;sub:string;icon:ReactNode;accent?:boolean}) { return <Panel className="p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-muted-foreground">{label}</p><div className="mt-2 font-display text-3xl font-extrabold tracking-tight" data-testid={`metric-${label.toLowerCase().replaceAll(' ','-')}`}>{value}</div><p className="mt-1 text-xs text-muted-foreground">{sub}</p></div><span className={`grid h-10 w-10 place-items-center rounded-xl ${accent?'bg-[#f8ebe1] text-[#b35d44]':'bg-[#e5efe7] text-primary'}`}>{icon}</span></div></Panel>; }
function useRoleFrame(role:'student'|'verifier'|'admin', children:ReactNode) {
  const nav = role==='student'?studentNav:role==='verifier'?verifierNav:adminNav;
  return <Gate role={role}><AppFrame section={role} nav={nav}>{children}</AppFrame></Gate>;
}

function RegistrationPage() {
  const {isSignedIn,isLoaded}=useUserAuth();
  const { data: me, isLoading: meLoading } = useGetMe({query:{enabled:isSignedIn&&isLoaded,queryKey:getGetMeQueryKey()}}); const { data: departments } = useListDepartments();
  const create = useCreateRegistration(); const qc=useQueryClient(); const [,setLoc]=useLocation();
  const [role,setRole]=useState<'student'|'verifier'>('student'); const [error,setError]=useState('');
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');const f=new FormData(e.currentTarget);
    const payload:any={role,fullName:String(f.get('fullName')||'').trim()};
    if(role==='student'){payload.studentId=String(f.get('studentId')||'').trim();payload.departmentId=String(f.get('departmentId')||'');payload.course=String(f.get('course')||'').trim();payload.yearOfStudy=Number(f.get('yearOfStudy'));payload.validityEnd=String(f.get('validityEnd')||'');}
    create.mutate({data:payload},{onSuccess:async()=>{await qc.invalidateQueries({queryKey:getGetMeQueryKey()});setLoc(role==='student'?'/student':'/verifier');},onError:()=>setError('We could not submit your details. Check each field and try again.')});
  };
  if(!isLoaded|| (isSignedIn&&meLoading))return <CenteredLoading/>;
  if(!isSignedIn)return <Redirect to="/sign-in"/>;
  if(me&&!me.needsRegistration&&me.role!=='unregistered')return <PortalRedirect/>;
  return <div className="app-grain min-h-[100dvh] bg-[#f4f1e8]"><header className="mx-auto flex max-w-6xl justify-between px-5 py-6 sm:px-10"><Brand/><Link href="/" className="text-sm font-semibold text-muted-foreground" data-testid="link-register-home">Return to home</Link></header><div className="mx-auto grid max-w-6xl gap-9 px-5 pb-16 pt-4 sm:px-10 lg:grid-cols-[.85fr_1.15fr]"><div className="pt-4"><p className="text-[10px] font-bold uppercase tracking-[.2em] text-[#b45f45]">First, let’s get you set up</p><h1 className="mt-3 font-display text-4xl font-extrabold leading-tight tracking-[-.05em] sm:text-5xl">Join your campus<br/>identity network.</h1><p className="mt-5 max-w-md leading-7 text-muted-foreground">Tell us how you’ll use DigiCampus ID. Student and verifier accounts are reviewed by your institution before access is activated.</p><div className="mt-8 space-y-3"><div className="flex gap-3 rounded-xl border border-border bg-card/70 p-4"><ShieldCheck className="mt-0.5 text-primary" size={18}/><p className="text-sm leading-6 text-muted-foreground">Your profile is private until you present your ID to an authorized verifier.</p></div><div className="flex gap-3 rounded-xl border border-border bg-card/70 p-4"><Clock3 className="mt-0.5 text-[#b0782d]" size={18}/><p className="text-sm leading-6 text-muted-foreground">Approval is required before you can issue or verify a campus identity.</p></div></div></div>
    <Panel className="p-5 sm:p-8"><div className="flex gap-2 rounded-xl bg-muted p-1.5"><button onClick={()=>setRole('student')} className={`flex-1 rounded-lg px-3 py-2.5 text-sm font-semibold transition ${role==='student'?'bg-card text-primary shadow-sm':'text-muted-foreground'}`} data-testid="button-role-student"><UserRound size={15} className="mr-1 inline"/>Student</button><button onClick={()=>setRole('verifier')} className={`flex-1 rounded-lg px-3 py-2.5 text-sm font-semibold transition ${role==='verifier'?'bg-card text-primary shadow-sm':'text-muted-foreground'}`} data-testid="button-role-verifier"><ScanLine size={15} className="mr-1 inline"/>Campus verifier</button></div>
    <form className="mt-6 space-y-4" onSubmit={submit}><Field label="Full name" name="fullName" placeholder="As it appears in campus records" required/><div className="rounded-xl bg-[#f4f1e8] px-4 py-3 text-xs text-muted-foreground" data-testid="text-account-email">Signed in as <strong className="text-foreground">{me?.email||'your verified email'}</strong></div>
    {role==='student'&&<><Field label="Student number" name="studentId" placeholder="Your institution-issued number" required/><label className="block space-y-1.5 text-xs font-semibold">Department<select name="departmentId" required className="w-full rounded-xl border border-input bg-card px-3 py-3 text-sm font-normal outline-none focus:ring-2 focus:ring-ring" data-testid="select-department"><option value="">Choose a department</option>{(departments||[]).filter(d=>d.isActive).map(d=><option key={d.id} value={d.id}>{d.name} · {d.code}</option>)}</select></label><Field label="Course / program" name="course" placeholder="e.g. Environmental Science" required/><div className="grid grid-cols-2 gap-3"><label className="block space-y-1.5 text-xs font-semibold">Year of study<select name="yearOfStudy" required className="w-full rounded-xl border border-input bg-card px-3 py-3 text-sm font-normal outline-none focus:ring-2 focus:ring-ring" data-testid="select-year"><option value="">Select year</option>{Array.from({length:10},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}</select></label><Field label="Expected end date" name="validityEnd" type="date" required/></div></>}
    {role==='verifier'&&<div className="rounded-xl border border-border bg-[#f4f1e8] p-4"><p className="text-sm font-semibold">Verifier access requires campus approval</p><p className="mt-1 text-xs leading-5 text-muted-foreground">Your institution will confirm your role and authorize your verification workspace.</p></div>}
    {error&&<p className="rounded-xl bg-[#f7e8e3] p-3 text-sm text-[#a94237]" role="alert" data-testid="text-registration-error">{error}</p>}
    <Button type="submit" disabled={create.isPending} className="w-full py-3" testId="button-submit-registration">{create.isPending?'Submitting application…':'Submit for approval'}<ArrowRight size={16}/></Button><p className="text-center text-[11px] leading-5 text-muted-foreground">By continuing, you confirm your information is accurate and belongs to you.</p></form></Panel></div></div>;
}
function Field({label,name,type='text',placeholder,required=false,value,onChange}: {label:string;name:string;type?:string;placeholder?:string;required?:boolean;value?:string|number;onChange?:(value:string)=>void}) {
  return <label className="block space-y-1.5 text-xs font-semibold">{label}<input name={name} type={type} placeholder={placeholder} required={required} value={value} onChange={onChange?(e)=>onChange(e.target.value):undefined} className="w-full rounded-xl border border-input bg-card px-3.5 py-3 text-sm font-normal outline-none transition placeholder:text-[#98a39d] focus:ring-2 focus:ring-ring" data-testid={`input-${name}`}/></label>;
}
function StudentDashboard() {
  const profile=useGetStudentProfile();const id=useGetStudentDigitalId();const logs=useListStudentVerifications();const requests=useGetStudentRequests();
  if(profile.isLoading||id.isLoading)return <Skeleton rows={5}/>;
  if(profile.isError)return <Notice title="Student dashboard unavailable" detail="We couldn't load your campus record right now." retry={()=>profile.refetch()}/>;
  const p=profile.data, digital=id.data;
  return <><PageHeading eyebrow="Student home" title={`Good to see you, ${p?.fullName?.split(' ')[0]||'student'}.`} description="Your campus identity, access status and recent activity." action={<Link href="/student/id" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-white" data-testid="link-view-id"><IdCard size={16}/>Open digital ID</Link>}/>
  <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="ID status" value={<span className="text-2xl"><Status value={digital?.status||p?.status}/></span>} sub="Your campus credential" icon={<BadgeCheck size={19}/>}/><Metric label="Student number" value={<span className="font-mono text-2xl">{p?.studentId||'—'}</span>} sub={p?.departmentName||'Department not set'} icon={<IdCard size={19}/>}/><Metric label="Recent checks" value={logs.data?.length??'—'} sub="Verifications on your ID" icon={<ScanLine size={19}/>} accent/><Metric label="Open requests" value={(requests.data?.lostReports?.filter(r=>r.status==='open').length||0)+(requests.data?.corrections?.filter(r=>r.status==='pending').length||0)} sub="Awaiting campus review" icon={<ClipboardList size={19}/>}/></div>
  <div className="mt-5 grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Digital identity</h2><p className="mt-1 text-xs text-muted-foreground">Ready when you need to show it.</p></div><Status value={digital?.status}/></div><div className="mt-5 grid gap-4 rounded-xl bg-[#f3f0e7] p-4 sm:grid-cols-[1fr_auto] sm:items-center"><div className="flex items-center gap-3"><span className="grid h-12 w-12 place-items-center rounded-full bg-[#d9e6da] font-bold text-primary">{initials(p?.fullName)}</span><div><p className="font-semibold" data-testid="text-student-name">{p?.fullName}</p><p className="text-xs text-muted-foreground">{p?.course} · Year {p?.yearOfStudy}</p></div></div><Link href="/student/id" className="inline-flex items-center gap-2 text-sm font-semibold text-primary" data-testid="link-show-id">Show my ID <ArrowRight size={15}/></Link></div><div className="mt-5 grid grid-cols-2 gap-4 text-sm"><div><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Department</p><p className="mt-1 font-semibold">{p?.departmentName||'—'}</p></div><div><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Valid through</p><p className="mt-1 font-semibold">{digital?.expiresAt?formatDate(digital.expiresAt):'Pending issue'}</p></div></div></Panel>
  <Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Recent verification</h2><p className="mt-1 text-xs text-muted-foreground">See when your ID was checked.</p></div><Link href="/student/history" className="text-xs font-bold text-primary" data-testid="link-all-history">Full history</Link></div><div className="mt-4 space-y-3">{(logs.data||[]).slice(0,4).map((log,i)=><LogRow key={log.id||i} log={log}/>) }{logs.isLoading&&<Skeleton rows={2}/>} {!logs.isLoading&&!logs.isError&&!logs.data?.length&&<Empty title="No checks yet" detail="When a campus team verifies your ID, the activity will appear here."/>}{logs.isError&&<Notice title="History is unavailable" detail="Your ID details are fine; activity just didn't load." retry={()=>logs.refetch()}/>}</div></Panel></div></>;
}
function initials(name?:string|null){return(name||'DC').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function formatDate(s?:string|null){if(!s)return'—';const d=new Date(s);return Number.isNaN(d.getTime())?s:new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(d);}
function formatTime(s?:string|null){if(!s)return'—';const d=new Date(s);return Number.isNaN(d.getTime())?s:new Intl.DateTimeFormat('en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(d);}
function LogRow({log}: {log:VerificationLog}) {return <div className="flex items-center justify-between gap-3 border-b border-[#eee9df] py-3 last:border-0" data-testid={`row-verification-${log.id}`}><div className="flex min-w-0 items-center gap-3"><span className={`grid h-9 w-9 shrink-0 place-items-center rounded-xl ${log.result==='verified'?'bg-[#e5efe7] text-primary':'bg-[#f7e8e3] text-[#a94237]'}`}>{log.result==='verified'?<Check size={16}/>:<CircleAlert size={16}/>}</span><div className="min-w-0"><p className="truncate text-sm font-semibold">{log.verifierName||'Campus verifier'}</p><p className="mt-0.5 text-xs text-muted-foreground">{log.method==='qr'?'QR scan':'Student number'} · {log.departmentName||'Campus'}</p></div></div><div className="shrink-0 text-right"><Status value={log.result}/><p className="mt-1 text-[10px] text-muted-foreground">{formatTime(log.createdAt)}</p></div></div>;}
function DigitalIdPage() {
  const {data:id,isLoading,isError,refetch}=useGetStudentDigitalId(); const profile=useGetStudentProfile();
  if(isLoading)return <Skeleton rows={4}/>;if(isError||!id)return <Notice title="Your digital ID is not ready" detail="We could not load your private credential. If your application is still pending, it will appear after approval." retry={()=>refetch()}/>;
  const p=profile.data;
  const downloadCard=()=>{const card=document.getElementById('printable-id');if(!card)return;const markup=`<!doctype html><html><head><meta charset="utf-8"><title>DigiCampus ID · ${id.studentId}</title><style>body{margin:0;background:#f3f0e7;display:grid;min-height:100vh;place-items:center;font-family:'DM Sans',sans-serif}.id-card{box-sizing:border-box;width:760px;min-height:430px;padding:38px;border-radius:26px;background:linear-gradient(135deg,#134e3a,#1d6151);color:#fbf6e9;position:relative;overflow:hidden}.id-card:after{content:"";position:absolute;inset:-50% -5% auto auto;width:60%;height:180%;border:1px solid #ffffff22;border-radius:50%}h2{margin:0;font-size:30px}.status-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor}</style></head><body><div class="id-card">${card.innerHTML}</div></body></html>`;const blob=new Blob([markup],{type:'text/html'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=`digicampus-id-${id.studentId}.html`;a.click();window.setTimeout(()=>URL.revokeObjectURL(href),1000);};
  return <><PageHeading eyebrow="Student identity" title="Your digital ID" description="This private credential is for you to present in person. Verifiers receive only the details required to confirm status." action={<div className="no-print flex flex-wrap gap-2"><Button variant="line" onClick={()=>window.print()} testId="button-print-id"><Printer size={16}/>Print</Button><Button variant="line" onClick={downloadCard} testId="button-download-card"><Download size={16}/>Download card</Button><a href={id.qrUrl} download={`digicampus-${id.studentId}-qr`} className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-white" data-testid="link-download-qr"><QrCode size={16}/>Save QR</a></div>}/>
  <div className="grid items-start gap-6 lg:grid-cols-[minmax(0,650px)_1fr]"><div id="printable-id" className="id-card min-h-[380px] rounded-[26px] p-6 shadow-[0_25px_65px_rgba(19,78,58,.2)] sm:p-8"><div className="relative z-[1] flex items-center justify-between"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl border border-white/20 bg-white/10"><Fingerprint size={23}/></span><div><p className="text-[9px] uppercase tracking-[.2em] text-white/60">DigiCampus ID</p><p className="font-display text-sm font-extrabold tracking-wide">CAMPUS IDENTITY</p></div></div><Status value={id.status}/></div><div className="relative z-[1] mt-8 flex gap-5 sm:mt-11"><div className="grid h-[92px] w-[92px] shrink-0 place-items-center overflow-hidden rounded-2xl border border-white/20 bg-[#d9bd87] text-2xl font-bold text-[#174b3a]">{id.photoUrl?<img src={id.photoUrl} alt={`${id.fullName} profile`} className="h-full w-full object-cover"/>:initials(id.fullName)}</div><div className="min-w-0 pt-1"><h2 className="font-display text-2xl font-extrabold tracking-tight sm:text-3xl" data-testid="text-id-student-name">{id.fullName}</h2><p className="mt-1 text-sm text-white/70">{id.departmentName}</p><p className="text-sm text-white/70">{id.course} · Year {id.yearOfStudy}</p></div></div><div className="relative z-[1] mt-8 flex items-end justify-between gap-3 border-t border-white/15 pt-5"><div className="space-y-3"><div><p className="text-[9px] uppercase tracking-[.17em] text-white/55">Student number</p><p className="mt-1 font-mono text-sm" data-testid="text-id-number">{id.studentId}</p></div><div className="flex gap-7"><div><p className="text-[9px] uppercase tracking-[.17em] text-white/55">Issued</p><p className="mt-1 font-mono text-xs">{formatDate(id.issuedAt)}</p></div><div><p className="text-[9px] uppercase tracking-[.17em] text-white/55">Expires</p><p className="mt-1 font-mono text-xs">{formatDate(id.expiresAt)}</p></div></div></div><div className="relative z-[1] h-[102px] w-[102px] shrink-0 overflow-hidden rounded-xl bg-[#fffdf8] p-2.5"><QrVisual value={id.qrUrl}/></div></div></div>
  <Panel className="no-print p-5 sm:p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e5efe7] text-primary"><ShieldCheck size={20}/></span><div><h2 className="font-display font-bold">Your privacy, in practice</h2><p className="text-xs text-muted-foreground">A verification never exposes your full profile.</p></div></div><ul className="mt-5 space-y-3 text-sm text-muted-foreground"><li className="flex gap-2"><Check size={15} className="mt-0.5 shrink-0 text-primary"/>Present the QR only to an authorized campus verifier.</li><li className="flex gap-2"><Check size={15} className="mt-0.5 shrink-0 text-primary"/>Scans confirm active status and basic campus affiliation.</li><li className="flex gap-2"><Check size={15} className="mt-0.5 shrink-0 text-primary"/>Your verification history stays visible in your account.</li></ul>{p?.status&&<div className="mt-5 border-t border-border pt-4 text-xs text-muted-foreground">Record status <span className="ml-2"><Status value={p.status}/></span></div>}</Panel></div></>;
}
function QrVisual({value}: {value:string}) {
  return <div className="grid h-full w-full place-items-center" aria-label="Private QR code"><QRCodeSVG value={value} size={82} bgColor="#fffdf8" fgColor="#173f33" level="M" includeMargin={false} title="Private DigiCampus ID QR code"/></div>;
}
function ProfilePage() {
  const {data:profile,isLoading,isError,refetch}=useGetStudentProfile();const {data:deps}=useListDepartments();const update=useUpdateStudentProfile();const qc=useQueryClient();const [saved,setSaved]=useState(false);
  if(isLoading)return <Skeleton rows={4}/>;if(isError||!profile)return <Notice title="Profile unavailable" detail="Your campus profile couldn't be loaded." retry={()=>refetch()}/>;
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);update.mutate({data:{course:String(f.get('course')),yearOfStudy:Number(f.get('yearOfStudy')),photoUrl:String(f.get('photoUrl')||'')||null} as never},{onSuccess:()=>{setSaved(true);qc.invalidateQueries({queryKey:getGetStudentProfileQueryKey()});setTimeout(()=>setSaved(false),2600);}});};
  return <><PageHeading eyebrow="Student account" title="Your profile" description="Your verified details are managed by your institution. You can update your study information here."/><div className="grid gap-5 lg:grid-cols-[.75fr_1.25fr]"><Panel className="p-6"><div className="grid h-16 w-16 place-items-center rounded-full bg-[#d9e6da] text-xl font-bold text-primary">{initials(profile.fullName)}</div><h2 className="mt-4 font-display text-xl font-extrabold">{profile.fullName}</h2><p className="mt-1 text-sm text-muted-foreground">{profile.email}</p><div className="mt-5"><Status value={profile.status}/></div><div className="mt-6 space-y-4 border-t border-border pt-5 text-sm"><div><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Student number</p><p className="mt-1 font-mono">{profile.studentId}</p></div><div><p className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Department</p><p className="mt-1">{profile.departmentName}</p></div></div></Panel><Panel className="p-6 sm:p-8"><div className="mb-6 flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><Pencil size={18}/></span><div><h2 className="font-display text-lg font-bold">Study details</h2><p className="text-xs text-muted-foreground">Changes may be reviewed by campus staff.</p></div></div><form className="space-y-4" onSubmit={submit}><Field label="Course / program" name="course" value={profile.course} required/><div className="grid gap-4 sm:grid-cols-2"><label className="block space-y-1.5 text-xs font-semibold">Year of study<select defaultValue={profile.yearOfStudy} name="yearOfStudy" className="w-full rounded-xl border border-input bg-card px-3 py-3 text-sm font-normal" data-testid="select-profile-year">{Array.from({length:10},(_,i)=><option key={i+1} value={i+1}>{i+1}</option>)}</select></label><Field label="Photo URL (optional)" name="photoUrl" placeholder="https://…" type="url" /></div><div className="rounded-xl bg-[#f4f1e8] p-4 text-xs leading-5 text-muted-foreground">For corrections to your legal name, student number or department, submit a formal correction request. These verified fields cannot be edited directly.</div>{saved&&<p className="text-sm font-semibold text-primary" role="status" data-testid="text-profile-saved"><Check size={15} className="mr-1 inline"/>Profile saved.</p>}<Button type="submit" disabled={update.isPending} testId="button-save-profile">{update.isPending?'Saving…':'Save changes'} <ArrowRight size={15}/></Button></form></Panel></div></>;
}
function HistoryPage() {
  const q=useListStudentVerifications();return <><PageHeading eyebrow="Student account" title="Verification history" description="Every check made against your digital ID. Only the verification outcome is stored here."/><Panel className="p-5 sm:p-7"><div className="mb-5 flex items-center justify-between"><h2 className="font-display font-bold">ID activity</h2><span className="text-xs text-muted-foreground">{q.data?.length??0} records</span></div>{q.isLoading?<Skeleton rows={5}/>:q.isError?<Notice title="History did not load" detail="Please try loading your verification records again." retry={()=>q.refetch()}/>:q.data?.length?<div>{q.data.map((log,i)=><LogRow key={log.id||i} log={log}/>)}</div>:<Empty title="No verification history" detail="Your ID has not been checked yet. When it is, the time and outcome will show here."/>}</Panel></>;
}
function RequestsPage() {
  const q=useGetStudentRequests();const report=useCreateLostReport();const correction=useCreateCorrectionRequest();const qc=useQueryClient();const [type,setType]=useState<'lost'|'correction'>('lost');const [message,setMessage]=useState('');
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setMessage('');const f=new FormData(e.currentTarget);const done=()=>{setMessage('Your request has been sent to campus administration.');qc.invalidateQueries({queryKey:getGetStudentRequestsQueryKey()});(e.target as HTMLFormElement).reset();};if(type==='lost')report.mutate({data:{reason:String(f.get('reason'))} as never},{onSuccess:done,onError:()=>setMessage('Request could not be submitted. Please try again.')});else correction.mutate({data:{field:String(f.get('field')),requestedValue:String(f.get('requestedValue')),reason:String(f.get('reason'))} as never},{onSuccess:done,onError:()=>setMessage('Request could not be submitted. Please try again.')});};
  return <><PageHeading eyebrow="Student account" title="Requests & support" description="Report a missing credential or ask to correct a verified record."/><div className="grid gap-5 xl:grid-cols-[1fr_1fr]"><Panel className="p-5 sm:p-7"><div className="flex gap-2 rounded-xl bg-muted p-1"><button onClick={()=>setType('lost')} className={`flex-1 rounded-lg px-3 py-2.5 text-sm font-semibold ${type==='lost'?'bg-card text-primary shadow-sm':'text-muted-foreground'}`} data-testid="button-request-lost">Lost ID</button><button onClick={()=>setType('correction')} className={`flex-1 rounded-lg px-3 py-2.5 text-sm font-semibold ${type==='correction'?'bg-card text-primary shadow-sm':'text-muted-foreground'}`} data-testid="button-request-correction">Correction</button></div><form onSubmit={submit} className="mt-5 space-y-4">{type==='correction'&&<><label className="block space-y-1.5 text-xs font-semibold">Field to correct<select name="field" className="w-full rounded-xl border border-input bg-card px-3 py-3 text-sm font-normal" data-testid="select-correction-field"><option value="fullName">Full name</option><option value="studentId">Student number</option><option value="department">Department</option><option value="course">Course</option><option value="yearOfStudy">Year of study</option></select></label><Field label="Requested value" name="requestedValue" placeholder="Enter the correct information" required/> </>}<label className="block space-y-1.5 text-xs font-semibold">{type==='lost'?'What happened?':'Reason for correction'}<textarea name="reason" minLength={5} maxLength={1000} required rows={4} placeholder={type==='lost'?'Tell us when you noticed it was missing…':'Please include enough detail for a campus review.'} className="w-full resize-y rounded-xl border border-input bg-card px-3.5 py-3 text-sm font-normal outline-none placeholder:text-[#98a39d] focus:ring-2 focus:ring-ring" data-testid="input-request-reason"/></label>{message&&<p className="text-sm text-primary" role="status" data-testid="text-request-feedback">{message}</p>}<Button type="submit" disabled={report.isPending||correction.isPending} testId="button-submit-request">{report.isPending||correction.isPending?'Sending…':'Submit request'}<ArrowRight size={15}/></Button></form></Panel><Panel className="p-5 sm:p-7"><h2 className="font-display text-lg font-bold">Your open requests</h2><p className="mt-1 text-xs text-muted-foreground">Status updates appear here when campus reviews the request.</p>{q.isLoading?<div className="mt-5"><Skeleton rows={3}/></div>:q.isError?<div className="mt-5"><Notice title="Requests unavailable" detail="We could not load your request history." retry={()=>q.refetch()}/></div>:<div className="mt-5 space-y-3">{[...(q.data?.lostReports||[]).map(r=>({...r,kind:'Lost ID report'})),...(q.data?.corrections||[]).map(r=>({...r,kind:`Correction · ${r.field}`}))].length===0?<Empty title="No requests submitted" detail="Lost ID reports and correction requests will appear here."/>:[...(q.data?.lostReports||[]).map(r=>({...r,kind:'Lost ID report'})),...(q.data?.corrections||[]).map(r=>({...r,kind:`Correction · ${r.field}`}))].map((r:any)=><div key={`${r.kind}-${r.id}`} className="flex items-start justify-between gap-3 rounded-xl border border-border p-4" data-testid={`row-request-${r.id}`}><div><p className="text-sm font-semibold">{r.kind}</p><p className="mt-1 line-clamp-2 text-xs text-muted-foreground">{r.reason||r.requestedValue}</p><p className="mt-2 text-[10px] text-muted-foreground">Submitted {formatDate(r.createdAt)}</p></div><Status value={r.status}/></div>)}</div>}</Panel></div></>;
}
function VerifierDashboard() {
  const q=useGetVerifierSummary();const logs=useListVerificationLogs({limit:6});
  if(q.isLoading)return <Skeleton rows={5}/>;
  if(q.isError)return <Notice title="Verifier overview unavailable" detail="Activity data is temporarily unavailable." retry={()=>q.refetch()}/>;
  const s=q.data;
  return <><PageHeading eyebrow="Campus verification" title="Verification desk" description="Confirm an ID’s campus status and keep the line moving." action={<Link href="/verify" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-white" data-testid="link-open-scanner"><ScanLine size={16}/>Verify a student</Link>}/>
  <div className="grid gap-4 sm:grid-cols-3"><Metric label="Checks today" value={s?.todayTotal??0} sub="QR and manual checks" icon={<Activity size={18}/>}/><Metric label="Confirmed" value={s?.successfulToday??0} sub="Active campus IDs" icon={<CheckCircle2 size={18}/>}/><Metric label="Needs attention" value={s?.failedToday??0} sub="Invalid or inactive IDs" icon={<CircleAlert size={18}/>} accent/></div>
  <div className="mt-5 grid gap-5 lg:grid-cols-[.82fr_1.18fr]"><Panel className="overflow-hidden"><div className="bg-[#194c3c] p-6 text-[#faf6e9]"><div className="flex items-center justify-between"><span className="grid h-11 w-11 place-items-center rounded-xl bg-white/10"><ScanLine size={22}/></span><span className="text-[10px] font-bold uppercase tracking-[.16em] text-white/60">Verifier station</span></div><h2 className="mt-6 font-display text-2xl font-extrabold">Ready to verify</h2><p className="mt-2 max-w-sm text-sm leading-6 text-white/70">Scan a private campus QR or enter a student number. You’ll see only essential identity status.</p><Link href="/verify" className="mt-5 inline-flex items-center gap-2 rounded-xl bg-[#f3e7c6] px-4 py-2.5 text-sm font-bold text-[#20352f]" data-testid="link-verify-start">Start a check <ArrowRight size={15}/></Link></div><div className="p-5"><div className="flex items-center gap-2 text-xs font-semibold"><ShieldCheck size={15} className="text-primary"/> Only essential details are shown</div><p className="mt-2 text-xs leading-5 text-muted-foreground">Each check is recorded for campus audit and the student’s transparency.</p></div></Panel><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Recent activity</h2><p className="mt-1 text-xs text-muted-foreground">The latest checks at your station.</p></div><Link href="/admin/verifications" className="text-xs font-bold text-primary" data-testid="link-verifier-full-log">View activity</Link></div><div className="mt-4">{logs.isLoading?<Skeleton rows={3}/>:logs.isError?<Notice title="Activity unavailable" detail="We couldn't load the latest checks." retry={()=>logs.refetch()}/>:logs.data?.length?logs.data.map((l,i)=><LogRow key={l.id||i} log={l}/>):<Empty title="No checks today" detail="Your completed verifications will appear here."/>}</div></Panel></div></>;
}
function VerifyPage() {
  const [studentId,setStudentId]=useState('');const [token,setToken]=useState('');const [result,setResult]=useState<VerificationResult|null>(null);const [attempted,setAttempted]=useState(false);
  const [cameraOn,setCameraOn]=useState(false);const [cameraError,setCameraError]=useState('');const videoRef=useRef<HTMLVideoElement|null>(null);const streamRef=useRef<MediaStream|null>(null);
  const manual=useVerifyStudentId();const qr=useVerifyQrToken();const qc=useQueryClient();const autoRef=useRef('');const qrMutateRef=useRef(qr.mutate);qrMutateRef.current=qr.mutate;
  const handleResult=(v:VerificationResult)=>{setResult(v);setAttempted(true);qc.invalidateQueries({queryKey:getGetVerifierSummaryQueryKey()});qc.invalidateQueries({queryKey:getListVerificationLogsQueryKey({limit:6})});qc.invalidateQueries({queryKey:getListVerificationLogsQueryKey({limit:100})});};
  const handleResultRef=useRef(handleResult);handleResultRef.current=handleResult;
  const stopCamera=()=>{streamRef.current?.getTracks().forEach(track=>track.stop());streamRef.current=null;setCameraOn(false);};
  const startCamera=async()=>{setCameraError('');if(!navigator.mediaDevices?.getUserMedia){setCameraError('Camera access is unavailable in this browser. Paste a QR token or use student number.');return;}try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});streamRef.current=stream;if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play();}setCameraOn(true);}catch{setCameraError('Camera permission was not granted. Paste a QR token or use student number instead.');}};
  useEffect(()=>{if(!cameraOn)return;const Detector=(window as any).BarcodeDetector;if(!Detector){setCameraError('QR camera scanning is not supported by this browser. Paste a QR token or use student number instead.');stopCamera();return;}const detector=new Detector({formats:['qr_code']});let active=true;let frame=0;const scan=async()=>{if(!active)return;try{const codes=await detector.detect(videoRef.current);const raw=String(codes?.[0]?.rawValue||'');if(raw){let value=raw;try{const parsed=new URL(raw);value=parsed.searchParams.get('token')||parsed.hash.replace(/^#.*token=/,'')||raw;}catch{}setToken(value);stopCamera();setAttempted(false);qrMutateRef.current({data:{token:value} as never},{onSuccess:handleResultRef.current,onError:()=>setAttempted(true)});return;}}catch{}frame=window.setTimeout(scan,170);};scan();return()=>{active=false;window.clearTimeout(frame);};},[cameraOn]);
  useEffect(()=>()=>{streamRef.current?.getTracks().forEach(track=>track.stop());},[]);
  useEffect(()=>{const t=new URLSearchParams(window.location.search).get('token');if(t&&autoRef.current!==t){autoRef.current=t;setToken(t);qr.mutate({data:{token:t} as never},{onSuccess:handleResult,onError:()=>setAttempted(true)});}},[]);
  const submitManual=(e:FormEvent)=>{e.preventDefault();setResult(null);setAttempted(false);manual.mutate({data:{studentId:studentId.trim()} as never},{onSuccess:handleResult,onError:()=>setAttempted(true)});};
  const submitToken=(e:FormEvent)=>{e.preventDefault();if(!token.trim())return;setResult(null);setAttempted(false);qr.mutate({data:{token:token.trim()} as never},{onSuccess:handleResult,onError:()=>setAttempted(true)});};
  const loading=manual.isPending||qr.isPending;const display=result;
  return <><PageHeading eyebrow="Verifier station" title="Verify a campus ID" description="Scan or enter an ID token to confirm current status. Never ask for a password or personal account details."/>
  <div className="grid items-start gap-5 xl:grid-cols-[1fr_.82fr]"><Panel className="overflow-hidden"><div className="border-b border-border px-5 py-4 sm:px-7"><div className="flex gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#e5efe7] text-primary"><ScanLine size={19}/></span><div><h2 className="font-display font-bold">Scan or enter a private QR token</h2><p className="mt-1 text-xs text-muted-foreground">Use a campus device camera or enter the private ID token.</p></div></div></div><div className="p-5 sm:p-7"><div className="mb-5 overflow-hidden rounded-2xl bg-[#192e2a]">{cameraOn?<div className="relative aspect-video"><video ref={videoRef} muted playsInline className="h-full w-full object-cover" data-testid="video-qr-camera"/><span className="pointer-events-none absolute inset-[18%] rounded-2xl border-2 border-[#d9bd87] shadow-[0_0_0_999px_rgba(0,0,0,.24)]"/></div>:<div className="flex items-center justify-between gap-4 p-4 text-white"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-white/10"><ScanLine size={19}/></span><div><p className="text-sm font-semibold">Camera scan</p><p className="mt-1 text-[11px] text-white/60">Point at a DigiCampus QR code.</p></div></div><Button variant="soft" className="shrink-0" onClick={startCamera} testId="button-start-camera"><ScanLine size={15}/>Start camera</Button></div>}{cameraOn&&<div className="flex items-center justify-between px-4 py-3 text-xs text-white"><span className="inline-flex items-center gap-2"><span className="h-2 w-2 animate-pulse rounded-full bg-[#a9d0a9]"/>Camera active · scanning for QR</span><Button variant="line" className="border-white/20 bg-transparent py-1.5 text-white hover:bg-white/10" onClick={stopCamera} testId="button-stop-camera">Stop</Button></div>}</div>{cameraError&&<p className="mb-4 rounded-xl bg-[#f7e8e3] p-3 text-xs leading-5 text-[#a94237]" role="alert" data-testid="text-camera-error">{cameraError}</p>}<form onSubmit={submitToken} className="space-y-3"><label className="block text-xs font-semibold" htmlFor="qr-token">QR token or private ID link</label><textarea id="qr-token" rows={3} value={token} onChange={e=>setToken(e.target.value)} placeholder="Paste the token or scan link from the student’s ID" className="w-full resize-none rounded-xl border border-input bg-card px-3.5 py-3 font-mono text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-qr-token"/><Button type="submit" disabled={loading||!token.trim()} className="w-full" testId="button-verify-token"><QrCode size={16}/>{qr.isPending?'Checking…':'Validate QR token'}</Button></form><div className="my-6 flex items-center gap-3 text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground"><span className="h-px flex-1 bg-border"/>or use student number<span className="h-px flex-1 bg-border"/></div><form onSubmit={submitManual} className="flex flex-col gap-3 sm:flex-row sm:items-end"><div className="flex-1"><Field label="Student number" name="student-lookup" value={studentId} onChange={setStudentId} placeholder="Enter campus student number" required/></div><Button type="submit" disabled={loading||studentId.trim().length<2} className="sm:mb-0.5" testId="button-verify-student-id"><Search size={16}/>{manual.isPending?'Checking…':'Check student ID'}</Button></form><div className="mt-6 flex gap-2 rounded-xl bg-[#f4f1e8] p-3 text-xs leading-5 text-muted-foreground"><LockKeyhole size={15} className="mt-0.5 shrink-0 text-primary"/>Verification returns only identity, campus affiliation and ID status. Checks are logged for audit.</div></div></Panel>
  <Panel className="min-h-[390px] p-5 sm:p-7"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Verification result</h2><p className="mt-1 text-xs text-muted-foreground">Result appears after a successful check.</p></div>{display&&<Status value={display.result}/>}</div>
    {loading?<div className="mt-8"><div className="h-16 animate-pulse rounded-2xl bg-muted"/><div className="mt-5 space-y-3"><div className="h-4 w-2/3 animate-pulse rounded bg-muted"/><div className="h-4 w-1/2 animate-pulse rounded bg-muted"/></div></div>:display?<div className="mt-6" data-testid="content-verification-result"><div className={`rounded-2xl p-5 ${display.result==='verified'?'bg-[#e5efe7] text-[#176347]':'bg-[#f7e8e3] text-[#963e34]'}`}><div className="flex items-center gap-3">{display.result==='verified'?<CheckCircle2 size={25}/>:<CircleAlert size={25}/>}<div><p className="font-display text-xl font-extrabold">{display.result==='verified'?'Identity verified':'ID requires attention'}</p><p className="mt-1 text-xs">{display.result==='verified'?'This campus ID is currently valid.':'The credential is not currently valid for campus access.'}</p></div></div></div><div className="mt-5 divide-y divide-border rounded-xl border border-border px-4">{[['Student',display.studentName],['Student number',display.studentId],['Department',display.departmentName],['Course',display.course],['Year of study',display.yearOfStudy],['Valid through',display.expiresAt?formatDate(display.expiresAt):null]].filter(([,v])=>v!==null&&v!==undefined).map(([label,value])=><div key={String(label)} className="flex justify-between gap-4 py-3 text-sm"><span className="text-muted-foreground">{label}</span><span className="text-right font-semibold" data-testid={`result-${String(label).toLowerCase().replaceAll(' ','-')}`}>{value}</span></div>)}</div><p className="mt-4 text-[11px] text-muted-foreground">Checked at {formatTime(display.checkedAt)}</p><Button className="mt-5" variant="line" onClick={()=>{setResult(null);setAttempted(false);setStudentId('');setToken('');}} testId="button-new-verification"><RefreshCw size={14}/>New check</Button></div>:attempted?<div className="mt-8 rounded-2xl border border-[#e4c3b9] bg-[#f7e8e3] p-5" data-testid="state-verification-error"><div className="flex gap-3 text-[#a94237]"><CircleAlert size={19}/><div><p className="font-bold">Could not validate this ID</p><p className="mt-1 text-xs leading-5">No student details are available. Confirm the token or student number and try again.</p></div></div><Button variant="line" className="mt-4" onClick={()=>setAttempted(false)} testId="button-dismiss-verify-error">Try another check</Button></div>:<div className="mt-8 flex min-h-[235px] flex-col items-center justify-center rounded-2xl border border-dashed border-border bg-[#f8f5ee] px-5 text-center"><span className="grid h-12 w-12 place-items-center rounded-2xl bg-white text-primary"><QrCode size={23}/></span><p className="mt-4 font-display font-bold">Ready for a campus check</p><p className="mt-1 max-w-xs text-xs leading-5 text-muted-foreground">Enter an ID above to see its status and essential campus details.</p></div>}
  </Panel></div></>;
}

function AdminDashboard() {
  const q=useGetAdminSummary();const registrations=useListRegistrations();const logs=useListVerificationLogs({limit:6});
  if(q.isLoading)return <Skeleton rows={5}/>;if(q.isError)return <Notice title="Administration overview unavailable" detail="We couldn't load campus metrics." retry={()=>q.refetch()}/>;
  const s=q.data;return <><PageHeading eyebrow="Institution administration" title="Campus identity overview" description="A clear view of registration, student records and verification activity." action={<Link href="/admin/approvals" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-white" data-testid="link-review-approvals"><ClipboardList size={16}/>Review approvals</Link>}/>
  <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Student records" value={s?.totalStudents??0} sub="Across campus" icon={<Users size={18}/>}/><Metric label="Active IDs" value={s?.activeIds??0} sub="Credentials in good standing" icon={<IdCard size={18}/>}/><Metric label="Pending approvals" value={s?.pendingApprovals??0} sub="Registrations awaiting review" icon={<Clock3 size={18}/>} accent/><Metric label="Checks today" value={s?.totalVerifications??0} sub={`${s?.failedVerificationsToday??0} need attention`} icon={<Activity size={18}/>}/></div>
  <div className="mt-5 grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Approval queue</h2><p className="mt-1 text-xs text-muted-foreground">Applications awaiting a decision.</p></div><Link href="/admin/approvals" className="text-xs font-bold text-primary" data-testid="link-all-approvals">Review queue</Link></div><div className="mt-4 space-y-2">{registrations.isLoading?<Skeleton rows={3}/>:registrations.isError?<Notice title="Queue unavailable" detail="Registration records did not load." retry={()=>registrations.refetch()}/>:registrations.data?.filter(r=>r.status==='pending').slice(0,4).map((r,i)=><div key={r.userId||i} className="flex items-center justify-between gap-3 rounded-xl bg-[#f4f1e8] p-3" data-testid={`row-pending-${r.userId}`}><div className="min-w-0"><p className="truncate text-sm font-semibold">{r.fullName}</p><p className="mt-0.5 text-xs text-muted-foreground">{r.role} · {r.departmentName||'Campus staff'}</p></div><Status value={r.status}/></div>)}{!registrations.isLoading&&!registrations.isError&&!registrations.data?.some(r=>r.status==='pending')&&<Empty title="Queue is clear" detail="New requests for campus access will appear here."/>}</div></Panel><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Recent verification activity</h2><p className="mt-1 text-xs text-muted-foreground">A live audit trail for campus checks.</p></div><Link href="/admin/verifications" className="text-xs font-bold text-primary" data-testid="link-all-verifications">Full activity</Link></div><div className="mt-4">{logs.isLoading?<Skeleton rows={3}/>:logs.isError?<Notice title="Activity unavailable" detail="Audit events could not be loaded." retry={()=>logs.refetch()}/>:logs.data?.length?logs.data.map((l,i)=><LogRow key={l.id||i} log={l}/>):<Empty title="No verification activity" detail="Campus checks will appear once a verifier submits one."/>}</div></Panel></div></>;
}
function AdminApprovals() {
  const q=useListRegistrations();const decide=useDecideRegistration();const qc=useQueryClient();const [busy,setBusy]=useState('');const [filter,setFilter]=useState('pending');
  const action=(userId:string,decision:'approve'|'reject')=>{setBusy(userId);decide.mutate({userId,data:{decision} as never},{onSuccess:()=>{qc.invalidateQueries({queryKey:getListRegistrationsQueryKey()});qc.invalidateQueries({queryKey:getGetAdminSummaryQueryKey()});setBusy('');},onError:()=>setBusy('error')});};
  const list=(q.data||[]).filter(r=>filter==='all'||r.status===filter);
  return <><PageHeading eyebrow="Administration" title="Registration approvals" description="Review campus access requests and approve only verified institutional affiliations."/><Panel className="overflow-hidden"><div className="flex flex-col gap-3 border-b border-border p-4 sm:flex-row sm:items-center sm:justify-between sm:px-6"><div><h2 className="font-display font-bold">Applications</h2><p className="mt-1 text-xs text-muted-foreground">{q.data?.length??0} applications on record</p></div><label className="flex items-center gap-2 text-xs font-semibold">Show<select value={filter} onChange={e=>setFilter(e.target.value)} className="rounded-lg border border-input bg-card px-3 py-2 text-sm" data-testid="select-approval-status"><option value="pending">Pending</option><option value="active">Approved</option><option value="rejected">Rejected</option><option value="all">All applications</option></select></label></div>
  {q.isLoading?<div className="p-5"><Skeleton rows={5}/></div>:q.isError?<div className="p-5"><Notice title="Applications unavailable" detail="We couldn't load registration submissions." retry={()=>q.refetch()}/></div>:list.length===0?<div className="p-5"><Empty title="No applications in this view" detail="There are no registration records matching this status."/></div>:<div className="divide-y divide-border">{list.map((r,i)=><div key={r.userId||i} className="grid gap-4 p-4 sm:grid-cols-[1fr_1fr_auto] sm:items-center sm:px-6" data-testid={`row-registration-${r.userId}`}><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-full bg-[#e5efe7] text-sm font-bold text-primary">{initials(r.fullName)}</span><div><p className="font-semibold">{r.fullName}</p><p className="text-xs text-muted-foreground">{r.email}</p></div></div><div className="grid grid-cols-2 gap-3 text-xs"><div><p className="text-muted-foreground">Role / department</p><p className="mt-1 font-semibold capitalize">{r.role} · {r.departmentName||'—'}</p></div><div><p className="text-muted-foreground">Student number</p><p className="mt-1 font-mono font-semibold">{r.studentId||'Not applicable'}</p></div></div><div className="flex items-center gap-2 sm:justify-end"><Status value={r.status}/>{r.status==='pending'&&<><Button className="px-3 py-2" disabled={busy===r.userId||decide.isPending} onClick={()=>action(r.userId,'approve')} testId={`button-approve-${r.userId}`}><Check size={14}/>Approve</Button><Button variant="line" className="px-3 py-2" disabled={busy===r.userId||decide.isPending} onClick={()=>action(r.userId,'reject')} testId={`button-reject-${r.userId}`}><X size={14}/>Reject</Button></>}</div>{busy==='error'&&<p className="text-xs text-[#a94237]" role="alert">Decision could not be saved. Try again.</p>}</div>)}</div>}</Panel></>;
}
function AdminStudents() {
  const [search,setSearch]=useState('');const [status,setStatus]=useState('all');const params=useMemo(()=>({search:search||undefined,status:status as any}),[search,status]);const q=useListStudents(params);const deps=useListAdminDepartments();const create=useCreateStudent();const update=useUpdateStudent();const setIdStatus=useUpdateDigitalIdStatus();const reissue=useReissueDigitalId();const qc=useQueryClient();const [newOpen,setNewOpen]=useState(false);const [editing,setEditing]=useState<any>(null);const [feedback,setFeedback]=useState('');
  const refresh=()=>{qc.invalidateQueries({queryKey:getListStudentsQueryKey()});qc.invalidateQueries({queryKey:getGetAdminSummaryQueryKey()});};
  const submitNew=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);const payload={email:String(f.get('email')),fullName:String(f.get('fullName')),studentId:String(f.get('studentId')),departmentId:String(f.get('departmentId')),course:String(f.get('course')),yearOfStudy:Number(f.get('yearOfStudy')),validityEnd:String(f.get('validityEnd'))};create.mutate({data:payload as never},{onSuccess:()=>{refresh();setNewOpen(false);setFeedback('Student record created.');},onError:()=>setFeedback('Student record could not be created.')});};
  const saveEdit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!editing)return;const f=new FormData(e.currentTarget);const data={fullName:String(f.get('fullName')),studentId:String(f.get('studentId')),departmentId:String(f.get('departmentId')),course:String(f.get('course')),yearOfStudy:Number(f.get('yearOfStudy'))};update.mutate({studentId:editing.studentId,data:data as never},{onSuccess:()=>{refresh();setEditing(null);setFeedback('Student record updated.');},onError:()=>setFeedback('Student record could not be updated.')});};
  const statusAction=(row:any,next:'active'|'suspended'|'revoked')=>setIdStatus.mutate({id:row.id,data:{status:next} as never},{onSuccess:refresh,onError:()=>setFeedback('ID status was not changed.')});
  return <><PageHeading eyebrow="Administration" title="Student records" description="Search campus records, review ID status and manage issued credentials." action={<Button onClick={()=>setNewOpen(!newOpen)} testId="button-add-student"><Plus size={16}/>{newOpen?'Close form':'Add student'}</Button>}/>
  {feedback&&<div className="mb-4 flex items-center justify-between rounded-xl border border-border bg-card px-4 py-3 text-sm" role="status" data-testid="text-student-feedback">{feedback}<button onClick={()=>setFeedback('')} aria-label="Dismiss message" data-testid="button-dismiss-student-feedback"><X size={15}/></button></div>}
  {newOpen&&<Panel className="mb-5 p-5 sm:p-6"><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-lg font-bold">Create student record</h2><button onClick={()=>setNewOpen(false)} aria-label="Close form" data-testid="button-close-add-student"><X size={17}/></button></div><form onSubmit={submitNew} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><Field label="Email" name="email" type="email" required/><Field label="Full name" name="fullName" required/><Field label="Student number" name="studentId" required/><label className="block space-y-1.5 text-xs font-semibold">Department<select name="departmentId" required className="w-full rounded-xl border border-input bg-card px-3 py-3 text-sm font-normal" data-testid="select-new-department"><option value="">Choose department</option>{(deps.data||[]).map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></label><Field label="Course" name="course" required/><Field label="Year of study" name="yearOfStudy" type="number" required/><Field label="Credential expires" name="validityEnd" type="date" required/><div className="flex items-end"><Button type="submit" disabled={create.isPending} testId="button-create-student">{create.isPending?'Creating…':'Create record'}<ArrowRight size={15}/></Button></div></form></Panel>}
  {editing&&<Panel className="mb-5 p-5 sm:p-6"><div className="mb-4 flex items-center justify-between"><h2 className="font-display text-lg font-bold">Edit {editing.fullName}</h2><button onClick={()=>setEditing(null)} aria-label="Close edit form" data-testid="button-close-edit-student"><X size={17}/></button></div><form onSubmit={saveEdit} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><Field label="Full name" name="fullName" value={editing.fullName} required/><Field label="Student number" name="studentId" value={editing.studentId} required/><Field label="Course" name="course" value={editing.course} required/><label className="block space-y-1.5 text-xs font-semibold">Department<select name="departmentId" defaultValue={editing.departmentId} className="w-full rounded-xl border border-input bg-card px-3 py-3 text-sm font-normal" data-testid="select-edit-department">{(deps.data||[]).map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></label><Field label="Year of study" name="yearOfStudy" type="number" value={editing.yearOfStudy} required/><div className="flex items-end"><Button type="submit" disabled={update.isPending} testId="button-save-student-edit">{update.isPending?'Saving…':'Save record'}</Button></div></form></Panel>}
  <Panel className="overflow-hidden"><div className="flex flex-col gap-3 border-b border-border p-4 sm:flex-row sm:items-center sm:px-5"><label className="relative flex-1"><span className="sr-only">Search student records</span><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search name, student number or email" className="w-full rounded-xl border border-input bg-card py-2.5 pl-9 pr-3 text-sm outline-none focus:ring-2 focus:ring-ring" data-testid="input-student-search"/></label><select value={status} onChange={e=>setStatus(e.target.value)} className="rounded-xl border border-input bg-card px-3 py-2.5 text-sm" aria-label="Filter by status" data-testid="select-student-status"><option value="all">All statuses</option><option value="pending">Pending</option><option value="active">Active</option><option value="suspended">Suspended</option><option value="revoked">Revoked</option><option value="expired">Expired</option></select></div>
  {q.isLoading?<div className="p-5"><Skeleton rows={5}/></div>:q.isError?<div className="p-5"><Notice title="Student records unavailable" detail="Search could not be completed." retry={()=>q.refetch()}/></div>:!q.data?.length?<div className="p-5"><Empty title="No student records found" detail={search?'Try another name or student number.':'Student records will appear here once they are created.'}/></div>:<div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left text-sm"><thead className="bg-[#f4f1e8] text-[10px] uppercase tracking-[.12em] text-muted-foreground"><tr><th className="px-5 py-3">Student</th><th className="px-4 py-3">ID number</th><th className="px-4 py-3">Department / course</th><th className="px-4 py-3">Record</th><th className="px-4 py-3">Credential</th><th className="px-5 py-3">Actions</th></tr></thead><tbody className="divide-y divide-border">{q.data.map((r:any)=><tr key={r.id} className="hover:bg-[#f9f7f1]" data-testid={`row-student-${r.id}`}><td className="px-5 py-4"><p className="font-semibold">{r.fullName}</p><p className="mt-1 text-xs text-muted-foreground">{r.email}</p></td><td className="px-4 py-4 font-mono text-xs">{r.studentId}</td><td className="px-4 py-4"><p className="text-xs font-semibold">{r.departmentName}</p><p className="mt-1 text-xs text-muted-foreground">{r.course} · Yr {r.yearOfStudy}</p></td><td className="px-4 py-4"><Status value={r.status}/></td><td className="px-4 py-4"><Status value={r.idStatus||'not issued'}/></td><td className="px-5 py-4"><div className="flex items-center gap-1.5"><button title="Edit student" onClick={()=>{setEditing(r);setNewOpen(false);}} className="rounded-lg p-2 text-primary hover:bg-[#e5efe7]" data-testid={`button-edit-student-${r.id}`}><Pencil size={15}/></button><button title="Reissue ID" onClick={()=>reissue.mutate({id:r.id},{onSuccess:refresh,onError:()=>setFeedback('ID could not be reissued.')})} className="rounded-lg p-2 text-primary hover:bg-[#e5efe7]" data-testid={`button-reissue-id-${r.id}`}><RefreshCw size={15}/></button>{r.idStatus==='active'?<button title="Suspend ID" onClick={()=>statusAction(r,'suspended')} className="rounded-lg p-2 text-[#a94237] hover:bg-[#f7e8e3]" data-testid={`button-suspend-id-${r.id}`}><LockKeyhole size={15}/></button>:<button title="Activate ID" onClick={()=>statusAction(r,'active')} className="rounded-lg p-2 text-primary hover:bg-[#e5efe7]" data-testid={`button-activate-id-${r.id}`}><BadgeCheck size={15}/></button>}</div></td></tr>)}</tbody></table></div>}</Panel></>;
}
function AdminVerifications() {
  const q=useListVerificationLogs({limit:100});
  return <><PageHeading eyebrow="Administration" title="Verification activity" description="Auditable campus ID checks. Each record contains only the minimum data required for institutional oversight."/><Panel className="overflow-hidden"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 className="font-display font-bold">Campus audit log</h2><p className="mt-1 text-xs text-muted-foreground">Latest checks by QR and manual ID lookup</p></div><span className="font-mono text-xs text-muted-foreground">{q.data?.length??0} EVENTS</span></div>{q.isLoading?<div className="p-5"><Skeleton rows={6}/></div>:q.isError?<div className="p-5"><Notice title="Verification log unavailable" detail="The campus audit stream did not load." retry={()=>q.refetch()}/></div>:!q.data?.length?<div className="p-5"><Empty title="No verification events" detail="Successful and unsuccessful checks will be recorded here."/></div>:<div className="overflow-x-auto"><table className="w-full min-w-[740px] text-left text-sm"><thead className="bg-[#f4f1e8] text-[10px] uppercase tracking-[.12em] text-muted-foreground"><tr><th className="px-5 py-3">Result</th><th className="px-4 py-3">Student</th><th className="px-4 py-3">Department</th><th className="px-4 py-3">Method</th><th className="px-4 py-3">Verifier</th><th className="px-5 py-3">Checked</th></tr></thead><tbody className="divide-y divide-border">{q.data.map((r,i)=><tr key={r.id||i} className="hover:bg-[#f9f7f1]" data-testid={`row-verification-log-${r.id}`}><td className="px-5 py-4"><Status value={r.result}/></td><td className="px-4 py-4"><p className="font-semibold">{r.studentName||'Unknown identity'}</p><p className="mt-1 font-mono text-xs text-muted-foreground">{r.studentId||'—'}</p></td><td className="px-4 py-4 text-xs">{r.departmentName||'—'}</td><td className="px-4 py-4"><span className="inline-flex items-center gap-1.5 text-xs"><span className="text-primary">{r.method==='qr'?<QrCode size={14}/>:<Search size={14}/>}</span>{r.method==='qr'?'QR scan':'Manual'}</span></td><td className="px-4 py-4 text-xs">{r.verifierName||'Campus verifier'}</td><td className="px-5 py-4 text-xs text-muted-foreground">{formatTime(r.createdAt)}</td></tr>)}</tbody></table></div>}</Panel></>;
}
function AdminDepartments() {
  const q=useListAdminDepartments();const create=useCreateDepartment();const update=useUpdateDepartment();const qc=useQueryClient();const [editing,setEditing]=useState<any>(null);const [error,setError]=useState('');
  const refresh=()=>{qc.invalidateQueries({queryKey:getListAdminDepartmentsQueryKey()});qc.invalidateQueries({queryKey:getListDepartmentsQueryKey()});};
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();setError('');const form=e.currentTarget;const f=new FormData(form);const data={name:String(f.get('name')).trim(),code:String(f.get('code')).trim().toUpperCase()};if(editing)update.mutate({id:editing.id,data:data as never},{onSuccess:()=>{refresh();setEditing(null);},onError:()=>setError('Department changes could not be saved.')});else create.mutate({data:data as never},{onSuccess:()=>{refresh();form.reset();},onError:()=>setError('Department could not be created. Check for a duplicate code.')});};
  const toggle=(d:any)=>update.mutate({id:d.id,data:{isActive:!d.isActive} as never},{onSuccess:()=>{refresh();qc.invalidateQueries({queryKey:getListDepartmentsQueryKey()});},onError:()=>setError('Department status could not be changed.')});
  return <><PageHeading eyebrow="Administration" title="Departments" description="Manage campus departments available during registration and student record review."/><div className="grid gap-5 lg:grid-cols-[.75fr_1.25fr]"><Panel className="p-5 sm:p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-secondary text-primary"><Plus size={18}/></span><div><h2 className="font-display font-bold">{editing?'Edit department':'Add a department'}</h2><p className="text-xs text-muted-foreground">{editing?'Update its name or campus code.':'Add an official campus unit.'}</p></div></div><form className="mt-5 space-y-4" onSubmit={submit}><Field label="Department name" name="name" value={editing?.name} placeholder="e.g. School of Public Health" required/><Field label="Short code" name="code" value={editing?.code} placeholder="e.g. SPH" required/>{error&&<p className="text-xs text-[#a94237]" role="alert" data-testid="text-department-error">{error}</p>}<div className="flex gap-2"><Button type="submit" disabled={create.isPending||update.isPending} testId="button-save-department">{create.isPending||update.isPending?'Saving…':editing?'Save changes':'Create department'}</Button>{editing&&<Button variant="line" onClick={()=>setEditing(null)} testId="button-cancel-department-edit">Cancel</Button>}</div></form></Panel><Panel className="overflow-hidden"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 className="font-display font-bold">Campus departments</h2><p className="mt-1 text-xs text-muted-foreground">Inactive departments are hidden from new registrations.</p></div><span className="font-mono text-xs text-muted-foreground">{q.data?.length??0}</span></div>{q.isLoading?<div className="p-5"><Skeleton rows={4}/></div>:q.isError?<div className="p-5"><Notice title="Departments unavailable" detail="Department records could not be loaded." retry={()=>q.refetch()}/></div>:!q.data?.length?<div className="p-5"><Empty title="No departments yet" detail="Create a department to make it available to campus registrations."/></div>:<div className="divide-y divide-border">{q.data.map(d=><div key={d.id} className="flex items-center justify-between gap-4 px-5 py-4" data-testid={`row-department-${d.id}`}><div><p className="font-semibold">{d.name}</p><div className="mt-1 flex items-center gap-2"><span className="font-mono text-[10px] text-muted-foreground">{d.code}</span><Status value={d.isActive?'active':'inactive'}/></div></div><div className="flex gap-1"><button onClick={()=>setEditing(d)} className="rounded-lg p-2 text-primary hover:bg-[#e5efe7]" aria-label={`Edit ${d.name}`} data-testid={`button-edit-department-${d.id}`}><Pencil size={15}/></button><button onClick={()=>toggle(d)} className="rounded-lg p-2 text-muted-foreground hover:bg-muted" aria-label={`${d.isActive?'Deactivate':'Activate'} ${d.name}`} data-testid={`button-toggle-department-${d.id}`}>{d.isActive?<Eye size={15}/>:<Eye size={15}/>}</button></div></div>)}</div>}</Panel></div></>;
}
function AdminRequests() {
  const q=useListAdminRequests();
  const lost=q.data?.lostReports||[], corrections=q.data?.corrections||[];
  return <><PageHeading eyebrow="Administration" title="Student requests" description="Review lost credential reports and requests to correct verified student details."/><div className="grid gap-5 lg:grid-cols-2"><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Lost ID reports</h2><p className="mt-1 text-xs text-muted-foreground">Reports that may require credential suspension.</p></div><span className="font-mono text-xs">{lost.length}</span></div>{q.isLoading?<div className="mt-4"><Skeleton rows={3}/></div>:q.isError?<div className="mt-4"><Notice title="Requests unavailable" detail="We couldn't load student requests." retry={()=>q.refetch()}/></div>:lost.length?<div className="mt-4 space-y-3">{lost.map(r=><div key={r.id} className="rounded-xl border border-border p-4" data-testid={`row-lost-report-${r.id}`}><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{r.studentName}</p><p className="font-mono text-xs text-muted-foreground">{r.studentId}</p></div><Status value={r.status}/></div><p className="mt-3 text-sm leading-6 text-muted-foreground">{r.reason}</p><p className="mt-2 text-[10px] text-muted-foreground">Reported {formatDate(r.createdAt)}</p></div>)}</div>:<div className="mt-4"><Empty title="No lost ID reports" detail="Student reports will be routed here for administrative review."/></div>}</Panel><Panel className="p-5 sm:p-6"><div className="flex items-center justify-between"><div><h2 className="font-display text-lg font-bold">Correction requests</h2><p className="mt-1 text-xs text-muted-foreground">Formal changes to verified student information.</p></div><span className="font-mono text-xs">{corrections.length}</span></div>{q.isLoading?<div className="mt-4"><Skeleton rows={3}/></div>:q.isError?<div className="mt-4"><Notice title="Requests unavailable" detail="We couldn't load student requests." retry={()=>q.refetch()}/></div>:corrections.length?<div className="mt-4 space-y-3">{corrections.map(r=><div key={r.id} className="rounded-xl border border-border p-4" data-testid={`row-correction-${r.id}`}><div className="flex items-start justify-between gap-3"><div><p className="font-semibold">{r.studentName}</p><p className="font-mono text-xs text-muted-foreground">{r.studentId}</p></div><Status value={r.status}/></div><div className="mt-3 rounded-lg bg-[#f4f1e8] p-3 text-xs"><span className="font-semibold capitalize">{r.field} → </span>{r.requestedValue}</div><p className="mt-2 text-xs leading-5 text-muted-foreground">{r.reason}</p><p className="mt-2 text-[10px] text-muted-foreground">Submitted {formatDate(r.createdAt)}</p></div>)}</div>:<div className="mt-4"><Empty title="No correction requests" detail="Requests submitted by students will appear here."/></div>}<p className="mt-4 border-t border-border pt-4 text-[11px] leading-5 text-muted-foreground">Review decisions are handled by the campus case management process. This view is read-only because no decision action is available in the connected API.</p></Panel></div></>;
}

function HealthBadge() {
  const health=useHealthCheck({query:{queryKey:getHealthCheckQueryKey(),refetchInterval:60000}});
  return <span className="inline-flex items-center gap-1.5 text-[10px] text-muted-foreground" data-testid="status-service-health"><span className={`h-1.5 w-1.5 rounded-full ${health.isError?'bg-[#a94237]':'bg-[#176347]'}`}/>{health.isError?'Service status unavailable':'Campus service operational'}</span>;
}
function NotFound() {return <div className="app-grain grid min-h-[100dvh] place-items-center bg-[#f5f2ea] p-5"><Panel className="w-full max-w-md p-8 text-center"><IconMark size={44}/><p className="mt-7 text-[10px] font-bold uppercase tracking-[.18em] text-[#b45f45]">404 · Page not found</p><h1 className="mt-2 font-display text-3xl font-extrabold">This campus path ends here.</h1><p className="mt-3 text-sm leading-6 text-muted-foreground">The page may have moved, or your link may be incomplete.</p><Link href="/" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-white" data-testid="link-notfound-home">Return to DigiCampus <ArrowLeft size={15}/></Link></Panel></div>;}
function RoutedErrorBoundary({children}:{children:ReactNode}) {const [location]=useLocation();return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>;}

function HomeRedirect() {return <><Show when="signed-in"><PortalRedirect/></Show><Show when="signed-out"><Home/></Show></>;}
function Router() {
  return <RoutedErrorBoundary><Switch>
    <Route path="/" component={HomeRedirect}/>
    <Route path="/sign-in/*?" component={()=> <AuthPage kind="in"/>}/>
    <Route path="/sign-up/*?" component={()=> <AuthPage kind="up"/>}/>
    <Route path="/register" component={RegistrationPage}/>
    <Route path="/student" component={()=>useRoleFrame('student',<StudentDashboard/>)}/>
    <Route path="/student/id" component={()=>useRoleFrame('student',<DigitalIdPage/>)}/>
    <Route path="/student/profile" component={()=>useRoleFrame('student',<ProfilePage/>)}/>
    <Route path="/student/history" component={()=>useRoleFrame('student',<HistoryPage/>)}/>
    <Route path="/student/requests" component={()=>useRoleFrame('student',<RequestsPage/>)}/>
    <Route path="/verifier" component={()=>useRoleFrame('verifier',<VerifierDashboard/>)}/>
    <Route path="/verify" component={()=>useRoleFrame('verifier',<VerifyPage/>)}/>
    <Route path="/admin" component={()=>useRoleFrame('admin',<AdminDashboard/>)}/>
    <Route path="/admin/approvals" component={()=>useRoleFrame('admin',<AdminApprovals/>)}/>
    <Route path="/admin/students" component={()=>useRoleFrame('admin',<AdminStudents/>)}/>
    <Route path="/admin/verifications" component={()=>useRoleFrame('admin',<AdminVerifications/>)}/>
    <Route path="/admin/departments" component={()=>useRoleFrame('admin',<AdminDepartments/>)}/>
    <Route path="/admin/requests" component={()=>useRoleFrame('admin',<AdminRequests/>)}/>
    <Route component={NotFound}/>
  </Switch></RoutedErrorBoundary>;
}
function ClerkCacheInvalidator() {
  const {addListener}=useClerk();const qc=useQueryClient();const prev=useRef<string|null|undefined>(undefined);
  useEffect(()=>{const unsub=addListener(({user})=>{const id=user?.id??null;if(prev.current!==undefined&&prev.current!==id)qc.clear();prev.current=id;});return unsub;},[addListener,qc]);return null;
}
function ClerkRoutes() {
  const [,setLocation]=useLocation();
  return <ClerkProvider publishableKey={clerkPubKey} proxyUrl={clerkProxyUrl} appearance={appearance} signInUrl={`${basePath}/sign-in`} signUpUrl={`${basePath}/sign-up`} localization={{signIn:{start:{title:'Welcome back',subtitle:'Sign in to access your campus identity'}},signUp:{start:{title:'Create your campus account',subtitle:'Get started with DigiCampus ID'}}}} routerPush={to=>setLocation(stripBase(to))} routerReplace={to=>setLocation(stripBase(to),{replace:true})}>
    <QueryClientProvider client={queryClient}><TooltipProvider><ClerkCacheInvalidator/><Router/><Toaster/></TooltipProvider></QueryClientProvider>
  </ClerkProvider>;
}
function App() {
  if(!clerkPubKey) return <div className="grid min-h-[100dvh] place-items-center bg-background p-6"><Notice title="Authentication setup is incomplete" detail="DigiCampus ID requires a Clerk publishable key before secure sign-in can begin."/></div>;
  return <WouterRouter base={basePath}><ClerkRoutes/></WouterRouter>;
}
export default App;
